%[text] %[text:anchor:T_D48C173C] # High Voltage Battery - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Random current
mdl = "BatteryHV_harness_model";
load_system(mdl)

% Load model parameters.
BatteryHV_ComponentTestParameters

% Select battery model.
% BatteryHV_useRefsub_Basic
BatteryHV_useRefsub_TableBasedSystem %[output:2c9bf4bd]
% Setup simulation case.
BatteryHV_setSimCase_Random( ... %[output:group:881eb29e] %[output:4b815ad9]
  RandomSeed = 125, ... %[output:4b815ad9]
  NumTransitions = 20, ... %[output:4b815ad9]
  InitialSOC_pct = 50 ); %[output:group:881eb29e] %[output:4b815ad9]
% Run simulation.
simOut = sim(mdl);

% Collect logged signals and visualize.
% The basic version of the battery block does not simulate battery temperature.
logged_signals = extractTimetable(simOut.logsout);
BatteryHV_plotResults(logged_signals); %[output:67adcecc]
